import type { NextConfig } from 'next';

const nextConfig: NextConfig = {};

export default nextConfig;

import { defineConfig } from 'vitest/config';

export default defineConfig({
  test: {
    environment: 'node',
    globals: true,
    include: ['tests/**/*.test.ts'],
  },
});

import js from '@eslint/js';
import tseslint from 'typescript-eslint';

export default [
  {
    ignores: ['.next/**', 'node_modules/**', 'coverage/**'],
  },
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    files: ['**/*.{ts,tsx}'],
    rules: {
      '@typescript-eslint/no-explicit-any': 'off',
      '@typescript-eslint/no-unused-vars': [
        'error',
        { argsIgnorePattern: '^_', varsIgnorePattern: '^_' },
      ],
      'no-undef': 'off',
    },
  },
];

{
  "singleQuote": true,
  "trailingComma": "all"
}

export type PubMedSource = 'fixture' | 'eutils';

export type Article = {
  pmid: string;
  title: string;
  authors: string[];
  journal: string;
  publicationDate: string;
  publicationTypes: string[];
  abstractText: string;
  abstractExcerpt: string;
  language: string;
  doi: string | null;
  pubmedUrl: string;
  retracted: boolean;
  corrected: boolean;
  source: string;
};

export type ArticleSearchResult = Article & {
  score: number;
  matchedTerms: string[];
};

export type SearchFilters = {
  fromYear?: number;
  toYear?: number;
  publicationTypes?: string[];
  journal?: string;
  language?: string;
};

export type SearchRequest = {
  query: string;
  page: number;
  pageSize: number;
  filters: SearchFilters;
};

export type SearchResponse = {
  query: string;
  page: number;
  pageSize: number;
  total: number;
  source: PubMedSource;
  results: ArticleSearchResult[];
  filters: SearchFilters;
};

export type ApiErrorCode =
  | 'bad_request'
  | 'not_found'
  | 'upstream_error'
  | 'configuration_error';

export type ApiErrorResponse = {
  error: {
    code: ApiErrorCode;
    message: string;
    details?: Record<string, unknown>;
  };
};

export type PubMedAdapter = {
  readonly source: PubMedSource;
  search(request: SearchRequest): Promise<SearchResponse>;
  getArticle(pmid: string): Promise<Article | null>;
};

import type { ApiErrorCode } from './types';

export class PubMedError extends Error {
  constructor(
    readonly code: ApiErrorCode,
    message: string,
    readonly status: number,
    readonly details?: Record<string, unknown>,
  ) {
    super(message);
    this.name = 'PubMedError';
  }
}

export function toErrorResponse(error: unknown) {
  if (error instanceof PubMedError) {
    return {
      status: error.status,
      body: {
        error: {
          code: error.code,
          message: error.message,
          details: error.details,
        },
      },
    };
  }

  return {
    status: 500,
    body: {
      error: {
        code: 'upstream_error' as const,
        message: 'The PubMed service could not complete the request.',
      },
    },
  };
}

import type { Article } from './types';

export function normalizePmid(value: string): string {
  return value.trim().replace(/[^0-9]/g, '');
}

export function pubmedUrl(pmid: string): string {
  return `https://pubmed.ncbi.nlm.nih.gov/${pmid}/`;
}

export function abstractExcerpt(abstractText: string, maxLength = 320): string {
  const compact = abstractText.replace(/\s+/g, ' ').trim();
  if (compact.length <= maxLength) {
    return compact;
  }

  return `${compact.slice(0, maxLength).replace(/[\s,.;:]+$/, '')}...`;
}

export function articleYear(article: Pick<Article, 'publicationDate'>): number | null {
  const match = article.publicationDate.match(/\d{4}/);
  return match ? Number(match[0]) : null;
}

export function uniqueStrings(values: Array<string | null | undefined>): string[] {
  return Array.from(
    new Set(
      values
        .map((value) => value?.trim())
        .filter((value): value is string => Boolean(value)),
    ),
  );
}

import { articleYear } from './normalize';
import type { Article, ArticleSearchResult, SearchFilters } from './types';

const TOKEN_PATTERN = /[a-z0-9]+/gi;
const STOP_WORDS = new Set([
  'a',
  'an',
  'and',
  'are',
  'as',
  'at',
  'for',
  'from',
  'how',
  'in',
  'is',
  'of',
  'on',
  'or',
  'the',
  'to',
  'what',
  'with',
]);

export function queryTerms(query: string): string[] {
  const terms = query.toLowerCase().match(TOKEN_PATTERN) ?? [];
  return Array.from(new Set(terms.filter((term) => !STOP_WORDS.has(term))));
}

export function filterArticles(
  articles: Article[],
  filters: SearchFilters,
): Article[] {
  return articles.filter((article) => {
    const year = articleYear(article);
    if (filters.fromYear && year && year < filters.fromYear) {
      return false;
    }
    if (filters.toYear && year && year > filters.toYear) {
      return false;
    }
    if (
      filters.language &&
      article.language.toLowerCase() !== filters.language.toLowerCase()
    ) {
      return false;
    }
    if (
      filters.journal &&
      !article.journal.toLowerCase().includes(filters.journal.toLowerCase())
    ) {
      return false;
    }
    if (filters.publicationTypes?.length) {
      const available = article.publicationTypes.map((type) => type.toLowerCase());
      const requested = filters.publicationTypes.map((type) => type.toLowerCase());
      if (!requested.some((type) => available.some((item) => item.includes(type)))) {
        return false;
      }
    }
    return true;
  });
}

export function rankArticles(
  articles: Article[],
  query: string,
): ArticleSearchResult[] {
  const terms = queryTerms(query);
  return articles
    .map((article) => {
      const haystacks = {
        title: article.title.toLowerCase(),
        abstract: article.abstractText.toLowerCase(),
        metadata: [
          article.journal,
          article.language,
          ...article.publicationTypes,
          ...article.authors,
        ]
          .join(' ')
          .toLowerCase(),
      };
      const matchedTerms = terms.filter(
        (term) =>
          haystacks.title.includes(term) ||
          haystacks.abstract.includes(term) ||
          haystacks.metadata.includes(term),
      );
      const score = terms.reduce((sum, term) => {
        let next = sum;
        if (haystacks.title.includes(term)) {
          next += 5;
        }
        if (haystacks.abstract.includes(term)) {
          next += 2;
        }
        if (haystacks.metadata.includes(term)) {
          next += 1;
        }
        return next;
      }, 0);
      const publicationYear = articleYear(article) ?? 0;
      const recencyScore = publicationYear > 0 ? publicationYear / 10_000 : 0;
      return {
        ...article,
        score: Number((score + recencyScore).toFixed(4)),
        matchedTerms,
      };
    })
    .filter((article) => terms.length === 0 || article.score > 0)
    .sort((left, right) => {
      if (right.score !== left.score) {
        return right.score - left.score;
      }
      return right.pmid.localeCompare(left.pmid);
    });
}

export function paginate<T>(items: T[], page: number, pageSize: number): T[] {
  const start = (page - 1) * pageSize;
  return items.slice(start, start + pageSize);
}

import { PubMedError } from './errors';
import type { SearchRequest } from './types';

const MAX_QUERY_LENGTH = 300;
const MAX_PAGE_SIZE = 25;

export function parseSearchParams(params: URLSearchParams): SearchRequest {
  const query = params.get('q')?.trim() ?? '';
  if (!query) {
    throw new PubMedError('bad_request', 'Search query parameter q is required.', 400);
  }
  if (query.length > MAX_QUERY_LENGTH) {
    throw new PubMedError(
      'bad_request',
      `Search query must be ${MAX_QUERY_LENGTH} characters or fewer.`,
      400,
    );
  }

  return {
    query,
    page: positiveInteger(params.get('page'), 1, 1, 10_000, 'page'),
    pageSize: positiveInteger(
      params.get('page_size'),
      10,
      1,
      MAX_PAGE_SIZE,
      'page_size',
    ),
    filters: {
      fromYear: optionalYear(params.get('from_year'), 'from_year'),
      toYear: optionalYear(params.get('to_year'), 'to_year'),
      publicationTypes: listParam(params.get('publication_types')),
      journal: optionalText(params.get('journal')),
      language: optionalText(params.get('language')),
    },
  };
}

function positiveInteger(
  value: string | null,
  fallback: number,
  min: number,
  max: number,
  name: string,
): number {
  if (!value) {
    return fallback;
  }
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < min || parsed > max) {
    throw new PubMedError(
      'bad_request',
      `${name} must be an integer from ${min} to ${max}.`,
      400,
    );
  }
  return parsed;
}

function optionalYear(value: string | null, name: string): number | undefined {
  if (!value) {
    return undefined;
  }
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < 1800 || parsed > 2100) {
    throw new PubMedError('bad_request', `${name} must be a four-digit year.`, 400);
  }
  return parsed;
}

function optionalText(value: string | null): string | undefined {
  const text = value?.trim();
  return text || undefined;
}

function listParam(value: string | null): string[] | undefined {
  const values = value
    ?.split(',')
    .map((item) => item.trim())
    .filter(Boolean);
  return values?.length ? values : undefined;
}

import fixture from '@/fixtures/pubmed.fixture.json';
import { filterArticles, paginate, rankArticles } from './ranking';
import type { Article, PubMedAdapter, SearchRequest, SearchResponse } from './types';

const fixtureArticles = fixture.articles as Article[];

export function createFixturePubMedAdapter(
  articles: Article[] = fixtureArticles,
): PubMedAdapter {
  return {
    source: 'fixture',
    async search(request: SearchRequest): Promise<SearchResponse> {
      const filtered = filterArticles(articles, request.filters);
      const ranked = rankArticles(filtered, request.query);
      return {
        query: request.query,
        page: request.page,
        pageSize: request.pageSize,
        total: ranked.length,
        source: 'fixture',
        results: paginate(ranked, request.page, request.pageSize),
        filters: request.filters,
      };
    },
    async getArticle(pmid: string): Promise<Article | null> {
      return articles.find((article) => article.pmid === pmid) ?? null;
    },
  };
}

import { XMLParser } from 'fast-xml-parser';
import { PubMedError } from './errors';
import { abstractExcerpt, pubmedUrl, uniqueStrings } from './normalize';
import { filterArticles, paginate, rankArticles } from './ranking';
import type { Article, PubMedAdapter, SearchRequest, SearchResponse } from './types';

type EutilsOptions = {
  email?: string;
  tool?: string;
  apiKey?: string;
  baseUrl?: string;
  fetchImpl?: typeof fetch;
};

const DEFAULT_BASE_URL = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils';
const parser = new XMLParser({
  ignoreAttributes: false,
  attributeNamePrefix: '@_',
  textNodeName: '#text',
  trimValues: true,
});

export function createEutilsPubMedAdapter(options: EutilsOptions): PubMedAdapter {
  const email = options.email?.trim();
  const tool = options.tool?.trim() || 'PubMedChatPrototype';
  const baseUrl = (options.baseUrl?.trim() || DEFAULT_BASE_URL).replace(/\/$/, '');
  const fetchImpl = options.fetchImpl ?? fetch;
  const cache = new Map<string, Article>();

  if (!email) {
    throw new PubMedError(
      'configuration_error',
      'PUBMED_EMAIL is required when PUBMED_SOURCE=eutils.',
      500,
    );
  }

  async function request(path: string, params: Record<string, string>): Promise<Response> {
    const url = new URL(`${baseUrl}/${path}`);
    for (const [key, value] of Object.entries({
      ...params,
      tool,
      email,
      ...(options.apiKey ? { api_key: options.apiKey } : {}),
    })) {
      url.searchParams.set(key, value);
    }

    let lastError: unknown;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 12_000);
        const response = await fetchImpl(url, { signal: controller.signal });
        clearTimeout(timeout);
        if (response.ok) {
          return response;
        }
        if (![429, 500, 502, 503, 504].includes(response.status)) {
          throw new PubMedError(
            'upstream_error',
            `PubMed E-utilities returned HTTP ${response.status}.`,
            502,
          );
        }
        lastError = new Error(`HTTP ${response.status}`);
      } catch (error) {
        lastError = error;
      }
      await new Promise((resolve) => setTimeout(resolve, 300 * (attempt + 1)));
    }

    throw new PubMedError(
      'upstream_error',
      'PubMed E-utilities did not respond successfully after retries.',
      502,
      { cause: lastError instanceof Error ? lastError.message : String(lastError) },
    );
  }

  async function fetchArticles(pmids: string[]): Promise<Article[]> {
    const missing = pmids.filter((pmid) => !cache.has(pmid));
    if (missing.length) {
      const response = await request('efetch.fcgi', {
        db: 'pubmed',
        id: missing.join(','),
        retmode: 'xml',
      });
      const xml = await response.text();
      for (const article of parsePubMedXml(xml)) {
        cache.set(article.pmid, article);
      }
    }
    return pmids.map((pmid) => cache.get(pmid)).filter((article): article is Article => Boolean(article));
  }

  return {
    source: 'eutils',
    async search(requestParams: SearchRequest): Promise<SearchResponse> {
      const response = await request('esearch.fcgi', {
        db: 'pubmed',
        term: requestParams.query,
        retmax: String(Math.min(100, requestParams.page * requestParams.pageSize + 25)),
        retmode: 'json',
        sort: 'relevance',
      });
      const data = await response.json();
      const ids = data?.esearchresult?.idlist;
      if (!Array.isArray(ids)) {
        throw new PubMedError(
          'upstream_error',
          'PubMed ESearch returned an unexpected response.',
          502,
        );
      }
      const articles = await fetchArticles(ids);
      const filtered = filterArticles(articles, requestParams.filters);
      const ranked = rankArticles(filtered, requestParams.query);
      return {
        query: requestParams.query,
        page: requestParams.page,
        pageSize: requestParams.pageSize,
        total: ranked.length,
        source: 'eutils',
        results: paginate(ranked, requestParams.page, requestParams.pageSize),
        filters: requestParams.filters,
      };
    },
    async getArticle(pmid: string): Promise<Article | null> {
      const [article] = await fetchArticles([pmid]);
      return article ?? null;
    },
  };
}

export function parsePubMedXml(xml: string): Article[] {
  const parsed = parser.parse(xml);
  const articles = asArray(parsed?.PubmedArticleSet?.PubmedArticle);
  return articles.map(normalizePubmedArticle).filter((article): article is Article => Boolean(article));
}

function normalizePubmedArticle(input: any): Article | null {
  const citation = input?.MedlineCitation;
  const article = citation?.Article;
  const pmid = text(citation?.PMID);
  const title = text(article?.ArticleTitle);
  if (!pmid || !title) {
    return null;
  }

  const abstractText = asArray(article?.Abstract?.AbstractText)
    .map((part) => {
      const label = stringValue(part?.['@_Label']);
      const value = text(part);
      return label && value ? `${label}: ${value}` : value;
    })
    .filter(Boolean)
    .join('\n\n');

  const publicationTypes = uniqueStrings(
    asArray(article?.PublicationTypeList?.PublicationType).map(text),
  );
  const articleIds = asArray(input?.PubmedData?.ArticleIdList?.ArticleId);
  const doi =
    articleIds.find((item) => item?.['@_IdType'] === 'doi') ?.
      ['#text'] ?? null;

  return {
    pmid,
    title,
    authors: normalizeAuthors(article?.AuthorList?.Author),
    journal: text(article?.Journal?.Title) || text(article?.Journal?.ISOAbbreviation),
    publicationDate: normalizeDate(article?.Journal?.JournalIssue?.PubDate),
    publicationTypes,
    abstractText,
    abstractExcerpt: abstractExcerpt(abstractText),
    language: text(article?.Language) || 'und',
    doi: typeof doi === 'string' ? doi : null,
    pubmedUrl: pubmedUrl(pmid),
    retracted: publicationTypes.includes('Retracted Publication'),
    corrected: publicationTypes.includes('Published Erratum'),
    source: 'pubmed-eutils',
  };
}

function normalizeAuthors(input: any): string[] {
  return uniqueStrings(
    asArray(input).map((author) => {
      const collective = text(author?.CollectiveName);
      if (collective) {
        return collective;
      }
      return [text(author?.ForeName), text(author?.LastName)].filter(Boolean).join(' ');
    }),
  );
}

function normalizeDate(pubDate: any): string {
  const year = text(pubDate?.Year);
  const month = monthNumber(text(pubDate?.Month));
  const day = text(pubDate?.Day).padStart(2, '0') || '01';
  if (year) {
    return `${year}-${month}-${day}`;
  }
  return text(pubDate?.MedlineDate);
}

function monthNumber(month: string): string {
  if (!month) {
    return '01';
  }
  if (/^\d+$/.test(month)) {
    return month.padStart(2, '0').slice(0, 2);
  }
  const months: Record<string, string> = {
    jan: '01',
    feb: '02',
    mar: '03',
    apr: '04',
    may: '05',
    jun: '06',
    jul: '07',
    aug: '08',
    sep: '09',
    oct: '10',
    nov: '11',
    dec: '12',
  };
  return months[month.slice(0, 3).toLowerCase()] ?? '01';
}

function asArray<T>(value: T | T[] | null | undefined): T[] {
  if (!value) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

function text(value: any): string {
  if (value == null) {
    return '';
  }
  if (typeof value === 'string' || typeof value === 'number') {
    return String(value).trim();
  }
  if (typeof value['#text'] === 'string' || typeof value['#text'] === 'number') {
    return String(value['#text']).trim();
  }
  return '';
}

function stringValue(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

import { createEutilsPubMedAdapter } from './eutils';
import { PubMedError } from './errors';
import { createFixturePubMedAdapter } from './fixtures';
import type { PubMedAdapter, PubMedSource } from './types';

let adapter: PubMedAdapter | null = null;

export function getPubMedAdapter(): PubMedAdapter {
  if (adapter) {
    return adapter;
  }

  const source = (process.env.PUBMED_SOURCE || 'fixture').toLowerCase() as PubMedSource;
  if (source === 'fixture') {
    adapter = createFixturePubMedAdapter();
    return adapter;
  }
  if (source === 'eutils') {
    adapter = createEutilsPubMedAdapter({
      email: process.env.PUBMED_EMAIL,
      tool: process.env.PUBMED_TOOL,
      apiKey: process.env.PUBMED_API_KEY,
      baseUrl: process.env.PUBMED_BASE_URL,
    });
    return adapter;
  }

  throw new PubMedError(
    'configuration_error',
    'PUBMED_SOURCE must be fixture or eutils.',
    500,
    { source },
  );
}

export function setPubMedAdapterForTest(nextAdapter: PubMedAdapter | null): void {
  adapter = nextAdapter;
}

import { NextResponse } from 'next/server';
import { toErrorResponse } from '@/pubmed/errors';

export function jsonError(error: unknown): NextResponse {
  const response = toErrorResponse(error);
  return NextResponse.json(response.body, { status: response.status });
}

