107	      const ids = data?.esearchresult?.idlist;
108	      if (!Array.isArray(ids)) {
109	        throw new PubMedError(
110	          'upstream_error',
111	          'PubMed ESearch returned an unexpected response.',
112	          502,
113	        );
114	      }
115	      const articles = await fetchArticles(ids);
116	      const filtered = filterArticles(articles, requestParams.filters);
117	      const ranked = rankArticles(filtered, requestParams.query);
118	      return {
119	        query: requestParams.query,
120	        page: requestParams.page,
121	        pageSize: requestParams.pageSize,
122	        total: ranked.length,
123	        source: 'eutils',
124	        results: paginate(ranked, requestParams.page, requestParams.pageSize),
125	        filters: requestParams.filters,
126	      };
127	    },
128	    async getArticle(pmid: string): Promise<Article | null> {
129	      const [article] = await fetchArticles([pmid]);
130	      return article ?? null;
131	    },
132	  };
133	}
134	
135	export function parsePubMedXml(xml: string): Article[] {
136	  const parsed = parser.parse(xml);
137	  const articles = asArray(parsed?.PubmedArticleSet?.PubmedArticle);
138	  return articles.map(normalizePubmedArticle).filter((article): article is Article => Boolean(article));
139	}
140	
141	function normalizePubmedArticle(input: any): Article | null {
142	  const citation = input?.MedlineCitation;
143	  const article = citation?.Article;
144	  const pmid = text(citation?.PMID);
145	  const title = text(article?.ArticleTitle);
146	  if (!pmid || !title) {
147	    return null;
148	  }
149	
150	  const abstractText = asArray(article?.Abstract?.AbstractText)
151	    .map((part) => {
152	      const label = stringValue(part?.['@_Label']);
153	      const value = text(part);
154	      return label && value ? `${label}: ${value}` : value;
155	    })
156	    .filter(Boolean)
157	    .join('\n\n');
158	
159	  const publicationTypes = uniqueStrings(
160	    asArray(article?.PublicationTypeList?.PublicationType).map(text),
161	  );
162	  const articleIds = asArray(input?.PubmedData?.ArticleIdList?.ArticleId);
163	  const doi =
164	    articleIds.find((item) => item?.['@_IdType'] === 'doi') ?.
165	      ['#text'] ?? null;
166	
167	  return {
168	    pmid,
169	    title,
170	    authors: normalizeAuthors(article?.AuthorList?.Author),
171	    journal: text(article?.Journal?.Title) || text(article?.Journal?.ISOAbbreviation),
172	    publicationDate: normalizeDate(article?.Journal?.JournalIssue?.PubDate),
173	    publicationTypes,
174	    abstractText,
175	    abstractExcerpt: abstractExcerpt(abstractText),
176	    language: text(article?.Language) || 'und',
177	    doi: typeof doi === 'string' ? doi : null,
178	    pubmedUrl: pubmedUrl(pmid),
179	    retracted: publicationTypes.includes('Retracted Publication'),
180	    corrected: publicationTypes.includes('Published Erratum'),
181	    source: 'pubmed-eutils',
182	  };
183	}
184	
185	function normalizeAuthors(input: any): string[] {
186	  return uniqueStrings(
187	    asArray(input).map((author) => {
188	      const collective = text(author?.CollectiveName);
189	      if (collective) {
190	        return collective;
191	      }
192	      return [text(author?.ForeName), text(author?.LastName)].filter(Boolean).join(' ');
193	    }),
194	  );
195	}
196	
197	function normalizeDate(pubDate: any): string {
198	  const year = text(pubDate?.Year);
199	  const month = monthNumber(text(pubDate?.Month));
200	  const day = text(pubDate?.Day).padStart(2, '0') || '01';
201	  if (year) {
202	    return `${year}-${month}-${day}`;
203	  }
204	  return text(pubDate?.MedlineDate);
205	}
206	
207	function monthNumber(month: string): string {
208	  if (!month) {
209	    return '01';
210	  }
211	  if (/^\d+$/.test(month)) {
212	    return month.padStart(2, '0').slice(0, 2);
213	  }
214	  const months: Record<string, string> = {
215	    jan: '01',
216	    feb: '02',
217	    mar: '03',
218	    apr: '04',
219	    may: '05',
220	    jun: '06',
221	    jul: '07',
222	    aug: '08',
223	    sep: '09',
224	    oct: '10',
225	    nov: '11',
226	    dec: '12',
227	  };
228	  return months[month.slice(0, 3).toLowerCase()] ?? '01';
229	}
230	
231	function asArray<T>(value: T | T[] | null | undefined): T[] {
232	  if (!value) {
233	    return [];
234	  }
235	  return Array.isArray(value) ? value : [value];
236	}
237	
238	function text(value: any): string {
239	  if (value == null) {
240	    return '';
241	  }
242	  if (typeof value === 'string' || typeof value === 'number') {
243	    return String(value).trim();
244	  }
245	  if (typeof value['#text'] === 'string' || typeof value['#text'] === 'number') {
246	    return String(value['#text']).trim();
247	  }
248	  return '';
249	}
250	
251	function stringValue(value: unknown): string {
252	  return typeof value === 'string' ? value.trim() : '';
253	}
